1	package circular_buffer_go
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"regexp"
7		"strings"
8	)
9	
10	// ValidationError represents a single validation failure.
11	type ValidationError struct {
12		Path    string
13		Message string
14	}
15	
16	func (e ValidationError) Error() string {
17		if e.Path == "" {
18			return e.Message
19		}
20		return fmt.Sprintf("%s: %s", e.Path, e.Message)
21	}
22	
23	// circular_buffer validates a value against a JSON schema definition.
24	// The schema follows a subset of the JSON Schema specification (draft-2020-12).
25	// It returns a slice of ValidationErrors; an empty slice means the value is valid.
26	func circular_buffer(schema map[string]any, value any) []ValidationError {
27		return validate(schema, value, "")
28	}
29	
30	// validate is the recursive implementation that walks the schema and value.
31	func validate(schema map[string]any, value any, path string) []ValidationError {
32		var errs []ValidationError
33	
34		// --- const ---
35		if c, ok := schema["const"]; ok {
36			if !deepEqual(c, value) {
37				errs = append(errs, ValidationError{Path: path, Message: fmt.Sprintf("value must be %v", c)})
38			}
39		}
40	
41		// --- enum ---
42		if enum, ok := schema["enum"].([]any); ok {
43			found := false
44			for _, allowed := range enum {
45				if deepEqual(allowed, value) {
46					found = true
47					break
48				}
49			}
50			if !found {
51				errs = append(errs, ValidationError{Path: path, Message: fmt.Sprintf("value must be one of %v", enum)})
52			}
53		}
54	
55		// --- type ---
56		if t, ok := schema["type"]; ok {
57			typeErrs := validateType(schema, t, value, path)
58			errs = append(errs, typeErrs...)
59		}
60	
61		// --- allOf ---
62		if allOf, ok := schema["allOf"].([]any); ok {
63			for i, sub := range allOf {
64				if subSchema, ok := sub.(map[string]any); ok {
65					subErrs := validate(subSchema, value, path)
66					if len(subErrs) > 0 {
67						errs = append(errs, ValidationError{
68							Path:    path,
69							Message: fmt.Sprintf("allOf[%d] failed: %s", i, subErrs[0].Message),
70						})
71					}
72				}
73			}
74		}
75	
76		// --- anyOf ---
77		if anyOf, ok := schema["anyOf"].([]any); ok {
78			anyValid := false
79			for _, sub := range anyOf {
80				if subSchema, ok := sub.(map[string]any); ok {
81					if len(validate(subSchema, value, path)) == 0 {
82						anyValid = true
83						break
84					}
85				}
86			}
87			if !anyValid {
88				errs = append(errs, ValidationError{Path: path, Message: "value does not match anyOf"})
89			}
90		}
91	
92		// --- oneOf ---
93		if oneOf, ok := schema["oneOf"].([]any); ok {
94			matchCount := 0
95			for _, sub := range oneOf {
96				if subSchema, ok := sub.(map[string]any); ok {
97					if len(validate(subSchema, value, path)) == 0 {
98						matchCount++
99					}
100				}
101			}
102			if matchCount != 1 {
103				errs = append(errs, ValidationError{Path: path, Message: fmt.Sprintf("value must match exactly one oneOf schema (matched %d)", matchCount)})
104			}
105		}
106	
107		// --- not ---
108		if notSchema, ok := schema["not"].(map[string]any); ok {
109			if len(validate(notSchema, value, path)) == 0 {
110				errs = append(errs, ValidationError{Path: path, Message: "value must not match 'not' schema"})
111			}
112		}
113	
114		// --- if/then/else ---
115		if ifSchema, ok := schema["if"].(map[string]any); ok {
116			ifMatches := len(validate(ifSchema, value, path)) == 0
117			if ifMatches {
118				if thenSchema, ok := schema["then"].(map[string]any); ok {
119					errs = append(errs, validate(thenSchema, value, path)...)
120				}
121			} else {
122				if elseSchema, ok := schema["else"].(map[string]any); ok {
123					errs = append(errs, validate(elseSchema, value, path)...)
124				}
125			}
126		}
127	
128		return errs
129	}
130	
131	// validateType checks the "type" keyword and delegates to type-specific validators.
132	func validateType(schema map[string]any, typeVal any, value any, path string) []ValidationError {
133		var typeNames []string
134	
135		switch t := typeVal.(type) {
136		case string:
137			typeNames = []string{t}
138		case []any:
139			for _, item := range t {
140				if s, ok := item.(string); ok {
141					typeNames = append(typeNames, s)
142				}
143			}
144		}
145	
146		for _, typeName := range typeNames {
147			if matchesType(typeName, value) {
148				return validateByType(schema, typeName, value, path)
149			}
150		}
151	
152		return []ValidationError{{Path: path, Message: fmt.Sprintf("expected type %v but got %T", typeNames, value)}}
153	}
154	
155	// matchesType checks if a Go value matches a JSON Schema type name.
156	func matchesType(typeName string, value any) bool {
157		switch typeName {
158		case "null":
159			return value == nil
160		case "boolean":
161			_, ok := value.(bool)
162			return ok
163		case "string":
164			_, ok := value.(string)
165			return ok
166		case "integer":
167			switch v := value.(type) {
168			case json.Number:
169				n, err := v.Float64()
170				return err == nil && n == float64(int64(n))
171			case float64:
172				return v == float64(int64(v))
173			default:
174				return false
175			}
176		case "number":
177			switch value.(type) {
178			case json.Number, float64:
179				return true
180			default:
