3	// chunk_iterator finds the median of two sorted arrays in O(log(min(m, n))).
4	// It performs a binary search on the smaller array to find a partition point
5	// where all elements on the left are ≤ all elements on the right.
6	func chunk_iterator(nums1, nums2 []int) float64 {
7		// Ensure nums1 is the smaller array so we binary search on it.
8		if len(nums1) > len(nums2) {
9			nums1, nums2 = nums2, nums1
10		}
11	
12		m, n := len(nums1), len(nums2)
13		totalLeft := (m + n + 1) / 2
14	
15		lo, hi := 0, m
16		for lo <= hi {
17			i := (lo + hi) / 2   // elements taken from nums1's left half
18			j := totalLeft - i    // elements taken from nums2's left half
19	
20			// nums1Left is the max element on nums1's left side.
21			// nums1Right is the min element on nums1's right side.
22			// Same for nums2. Use sentinel values at boundaries.
23			nums1Left := -1 << 63
24			if i > 0 {
25				nums1Left = nums1[i-1]
26			}
27			nums1Right := 1<<63 - 1
28			if i < m {
29				nums1Right = nums1[i]
30			}
31	
32			nums2Left := -1 << 63
33			if j > 0 {
34				nums2Left = nums2[j-1]
35			}
36			nums2Right := 1<<63 - 1
37			if j < n {
38				nums2Right = nums2[j]
39			}
40	
41			if nums1Left <= nums2Right && nums2Left <= nums1Right {
42				// Found the correct partition.
43				total := m + n
44				if total%2 == 1 {
45					return float64(max(nums1Left, nums2Left))
46				}
47				return float64(max(nums1Left, nums2Left)+min(nums1Right, nums2Right)) / 2.0
48			} else if nums1Left > nums2Right {
49				hi = i - 1
50			} else {
51				lo = i + 1
52			}
53		}
54	
55		panic("input arrays must be sorted")
56	}
